const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const warburtonCreek = ee.Geometry.Point([139.5, -26.5]); // Warburton Creek approximate location
  const buffer = warburtonCreek.buffer(10000); // 10km buffer

  const date1 = '2025-06-20';
  const date2 = '2025-09-15';

  // 2. Data Acquisition & Check
  // Try Sentinel-2
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(buffer)
    .filterDate(date1, ee.Date(date1).advance(10, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(buffer)
    .filterDate(date2, ee.Date(date2).advance(10, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`June 2025 Images: ${size1}`);
  console.log(`September 2025 Images: ${size2}`);

  // Fallback to Landsat 9 if Sentinel-2 fails
  if (size1 === 0 || size2 === 0) {
    col1 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(buffer)
      .filterDate(date1, ee.Date(date1).advance(10, 'day'))
      .filter(ee.Filter.lt('CLOUD_COVER', 50));

    col2 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(buffer)
      .filterDate(date2, ee.Date(date2).advance(10, 'day'))
      .filter(ee.Filter.lt('CLOUD_COVER', 50));

    const ls_size1 = await col1.size().getInfo();
    const ls_size2 = await col2.size().getInfo();

    console.log(`Landsat9 June: ${ls_size1}, September: ${ls_size2}`);

    if (ls_size1 === 0 || ls_size2 === 0) {
      console.log('No data available for one or both dates');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Cloud masking and NDVI calculation
  function maskCloudsS2(image) {
    const qa = image.select('QA60');
    const cloudMask = qa.bitwiseAnd(1 << 10).eq(0)
      .and(qa.bitwiseAnd(1 << 11).eq(0));
    return image.updateMask(cloudMask);
  }

  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // Process collections
  const img1 = col1.map(maskCloudsS2).map(addNDVI).median();
  const img2 = col2.map(maskCloudsS2).map(addNDVI).median();

  // Check pixel counts
  const count1_result = await img1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const count2_result = await img2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const count1 = count1_result.NDVI || 0;
  const count2 = count2_result.NDVI || 0;

  console.log(`Valid pixels - June: ${count1}, September: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculate mean NDVI
  const ndvi1_result = await img1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const ndvi2_result = await img2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: buffer,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const ndvi1 = ndvi1_result.NDVI;
  const ndvi2 = ndvi2_result.NDVI;

  console.log(`June NDVI: ${ndvi1 !== null ? ndvi1.toFixed(3) : 'null'}`);
  console.log(`September NDVI: ${ndvi2 !== null ? ndvi2.toFixed(3) : 'null'}`);

  // 5. Validation & Final Answer
  if (ndvi1 === null || ndvi2 === null || isNaN(ndvi1) || isNaN(ndvi2) || 
      ndvi1 > 1 || ndvi1 < -1 || ndvi2 > 1 || ndvi2 < -1) {
    console.log('Invalid NDVI calculation');
    console.log('<answer>C3</answer>');
    return;
  }

  const change = ndvi2 - ndvi1;
  console.log(`NDVI Change: ${change.toFixed(3)}`);

  if (change > 0) {
    console.log('Vegetation cover increased');
    console.log('<answer>A</answer>');
  } else {
    console.log('Vegetation cover did not increase');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
